52	// This pass traverses the AST, splits the target function into host and device
53	// parts, and preserves assumptions on every side that can evaluate them.
54	
55	// 1. Traverse AST and collect all optimizer assumptions into host_assumes_.
56	// 2. Until the first AttrStmtNode with tvm::attr::kTarget.
57	// 3. Call SplitDeviceFunc, which will create a new device function and replace
58	//    the original body with a call to that function. Host-evaluable runtime
59	//    checks found in the device body are attached to that host-side call.
60	class HostDeviceSplitter : public tirx::StmtMutator {
61	public:
62	  explicit HostDeviceSplitter(IRModule *device_mod,
63	                              std::function<GlobalVar()> var_supply)
64	      : device_mod_(device_mod), var_supply_(std::move(var_supply)) {}
65	
66	  void SetNonRestrictParams(const Array<tirx::Var> &params) {
67	    for (auto param : params) {
68	      non_restrict_params_.push_back(param);
69	    }
70	  }
71	
72	  void SetClusterDims(Array<Integer> cluster_dims) {
73	    cluster_dims_ = std::move(cluster_dims);
74	  }
75	
76	  void SetSmemAlignmentMap(Map<String, IntImm> smem_alignment_map) {
77	    smem_alignment_map_ = std::move(smem_alignment_map);
78	  }
79	
80	  void SetHostFuncSignature(const tirx::PrimFunc &func) {
81	    host_buffer_map_ = func->buffer_map;
82	  }
83	
84	  tirx::Stmt VisitStmt_(const tirx::AttrStmtNode *op) final {
85	    if (op->attr_key == tvm::attr::kTarget) {
86	      found_device_region_ = true;
87	      auto device_target = op->node.as<tvm::Target>().value().WithoutHost();
88	      return SplitDeviceFunc(op->body, device_target);
89	    } else if (op->attr_key == tirx::attr::tilelang_assume) {
90	      // NOTE(chaofan): the assumes collected here must be in host-side.
91	      //    This is because when the collector reaches the split region,
92	      //    it will start to split and return. For safety, we add a check here.
93	      ICHECK(!found_device_region_)
94	          << "Assumes collection should not be in device region.";
95	      // We first push back the outside assume, then visit the child.
96	      // So when moving assumes to device side, we need to do the building
97	      // process in a reverse order.
98	      host_assumes_.push_back(GetRef<tirx::AttrStmt>(op));
99	    }
100	    return tirx::StmtMutator::VisitStmt_(op);
101	  }
102	
103	  tirx::Stmt VisitStmt_(const tirx::EvaluateNode *op) final {
104	    auto stmt = GetRef<tirx::Stmt>(op);
105	    // There should be no assume in evaluate form after InjectAssumes.
106	    ICHECK(!IsAssumeInEvaluateForm(stmt))
107	        << "Unexpected assume in evaluate form. Please run InjectAssumes pass "
108	           "first.";
109	    return tirx::StmtMutator::VisitStmt_(op);
110	  }
111	
112	  tirx::Stmt ForceSplit(tirx::Stmt body, tvm::Target device_target) {
113	    return SplitDeviceFunc(std::move(body), std::move(device_target));
114	  }
115	
116	  bool found_device_region() const { return found_device_region_; }
117	
118	private:
119	  struct RuntimeCheckInfo {
120	    PrimExpr condition;
121	    StringImm message;
122	    Span span;
123	  };
124	
125	  class HostEvaluableConditionChecker : public tirx::StmtExprVisitor {
126	  public:
127	    explicit HostEvaluableConditionChecker(const Array<tirx::Var> &params) {
128	      for (const tirx::Var &param : params) {
129	        if (!param->dtype.is_handle()) {
130	          params_.insert(param);
131	        }
132	      }
133	    }
134	
135	    bool Check(const PrimExpr &condition) {
136	      if (!condition->dtype.is_bool() || condition->dtype.lanes() != 1) {
137	        return false;
138	      }
139	      VisitExpr(condition);
140	      return is_host_evaluable_;
141	    }
142	
143	  private:
144	    void VisitExpr_(const tirx::VarNode *op) final {
145	      if (!params_.count(GetRef<tirx::Var>(op))) {
146	        is_host_evaluable_ = false;
147	      }
148	    }
149	
150	    void VisitExpr_(const tirx::BufferLoadNode *op) final {
151	      is_host_evaluable_ = false;
152	    }
153	
154	    void VisitExpr_(const tirx::CallNode *op) final {
155	      // Device intrinsics and memory-dependent calls cannot be evaluated by
156	      // the host launcher. Keep this deliberately conservative; ordinary
157	      // shape constraints use arithmetic expression nodes rather than calls.
158	      is_host_evaluable_ = false;
159	    }
160	
161	    std::unordered_set<tirx::Var, ObjectPtrHash, ObjectPtrEqual> params_;
162	    bool is_host_evaluable_{true};
163	  };
164	
165	  class DeviceRuntimeCheckCollector : public tirx::StmtVisitor {
166	  public:
167	    static std::vector<RuntimeCheckInfo>
168	    Collect(const Stmt &body, const Array<tirx::Var> &params) {
169	      DeviceRuntimeCheckCollector collector(params);
170	      collector(body);
171	      return collector.runtime_checks_;
172	    }
173	
174	  private:
175	    explicit DeviceRuntimeCheckCollector(const Array<tirx::Var> &params)
176	        : params_(params) {}
177	
178	    void VisitStmt_(const tirx::AttrStmtNode *op) final {
179	      if (op->attr_key == tl::attr::kAssumeRequiresRuntimeCheck &&
180	          conditional_scope_depth_ == 0) {
181	        PrimExpr condition = Downcast<PrimExpr>(op->node);
182	        HostEvaluableConditionChecker checker(params_);
183	        if (checker.Check(condition)) {
184	          StringImm message = [&]() {
185	            if (const auto *string_imm = op->value.as<StringImmNode>()) {
186	              return GetRef<StringImm>(string_imm);
187	            }
188	            std::ostringstream os;
189	            os << "Assume: " << condition;
190	            return StringImm(os.str());
191	          }();
192	          runtime_checks_.push_back({condition, message, op->span});
193	        }
194	      }
195	      tirx::StmtVisitor::VisitStmt_(op);
196	    }
197	
198	    void VisitStmt_(const tirx::IfThenElseNode *op) final {
199	      ++conditional_scope_depth_;
200	      tirx::StmtVisitor::VisitStmt_(op);
201	      --conditional_scope_depth_;
202	    }
203	
204	    void VisitStmt_(const tirx::ForNode *op) final {
205	      ++conditional_scope_depth_;
206	      tirx::StmtVisitor::VisitStmt_(op);
207	      --conditional_scope_depth_;
208	    }
209	
210	    void VisitStmt_(const tirx::WhileNode *op) final {
211	      ++conditional_scope_depth_;
212	      tirx::StmtVisitor::VisitStmt_(op);
213	      --conditional_scope_depth_;
214	    }
215	
216	    Array<tirx::Var> params_;
217	    std::vector<RuntimeCheckInfo> runtime_checks_;
218	    int conditional_scope_depth_{0};
219	  };
220	
221	  class RuntimeCheckMarkerRemover : public tirx::StmtMutator {
222	  public:
223	    static Stmt Remove(Stmt body) {
224	      RuntimeCheckMarkerRemover remover;
225	      return remover(std::move(body));
226	    }
227	
228	  private:
229	    Stmt VisitStmt_(const tirx::AttrStmtNode *op) final {
230	      if (op->attr_key == tl::attr::kAssumeRequiresRuntimeCheck) {
231	        return VisitStmt(op->body);
232	      }
233	      return tirx::StmtMutator::VisitStmt_(op);
234	    }
235	  };
236	
237	  bool found_device_region_{false};
238	  Map<tirx::Var, tirx::Buffer> host_buffer_map_;
239	  Array<tirx::Var> non_restrict_params_;
240	  Optional<Array<Integer>> cluster_dims_{std::nullopt};
241	  // Per-buffer shared-memory alignment requirements (kSmemAlignmentMap)
242	  // propagated from the host PrimFunc onto each split device kernel.
243	  Map<String, IntImm> smem_alignment_map_;
244	  Optional<String> code_block_source_{std::nullopt};
245	  Optional<String> code_block_entry_name_{std::nullopt};
246	
247	  static void SortDeviceParams(std::vector<tirx::Var> *params) {
248	    std::sort(params->begin(), params->end(),
249	              [](const tirx::Var &a, const tirx::Var &b) {
250	                auto sort_key = [](const tirx::Var &var) {
251	                  return std::tuple{
252	                      !var->dtype.is_handle(),
253	                      var->name_hint,
254	                  };
255	                };
256	                return sort_key(a) < sort_key(b);
257	              });
258	  }
259	
260	  std::tuple<Array<tirx::Var>, Array<tirx::Buffer>>
261	  CollectSourceKernelSignature() const {
262	    std::vector<tirx::Var> params;
263	    std::unordered_set<std::string> seen_vars;
264	
265	    auto push = [&](const tirx::Var &var) {
266	      if (var.defined() && seen_vars.insert(var->name_hint).second) {
267	        params.push_back(var);
268	      }
269	    };
270	
271	    Array<tirx::Buffer> buffers_to_declare;
272	    for (const auto &kv : host_buffer_map_) {
273	      const tirx::Buffer &buf = kv.second;
274	      push(buf->data);
275	      buffers_to_declare.push_back(buf);
276	      for (const PrimExpr &dim : buf->shape) {
277	        if (const auto *var = dim.as<tirx::VarNode>()) {
278	          push(GetRef<tirx::Var>(var));
279	        }
280	      }
281	      for (const PrimExpr &stride : buf->strides) {
282	        if (const auto *var = stride.as<tirx::VarNode>()) {
283	          push(GetRef<tirx::Var>(var));
284	        }
285	      }
286	      if (const auto *var = buf->elem_offset.as<tirx::VarNode>()) {
287	        push(GetRef<tirx::Var>(var));
288	      }
289	    }
290	
291	    SortDeviceParams(&params);
292	    return {Array<tirx::Var>(params.begin(), params.end()), buffers_to_declare};
293	  }
294	
295	  class SourceKernelAttrExtractor : public tirx::StmtMutator {
296	  public:
297	    static Stmt Extract(Stmt body, Optional<String> *code_block_source,
298	                        Optional<String> *code_block_entry_name) {
299	      SourceKernelAttrExtractor extractor(code_block_source,
300	                                          code_block_entry_name);
301	      return extractor(std::move(body));
302	    }
303	
304	  private:
305	    explicit SourceKernelAttrExtractor(Optional<String> *code_block_source,
306	                                       Optional<String> *code_block_entry_name)
307	        : code_block_source_(code_block_source),
308	          code_block_entry_name_(code_block_entry_name) {}
309	
310	    Stmt VisitStmt_(const tirx::AttrStmtNode *op) final {
311	      if (op->attr_key == tl::attr::kCodeBlockSource) {
312	        if (auto str = op->value.as<StringImmNode>()) {
313	          *code_block_source_ = str->value;
314	        } else {
315	          LOG(FATAL) << "Expected `" << tl::attr::kCodeBlockSource
316	                     << "` AttrStmt to carry a StringImm value, but got "
317	                     << op->value->GetTypeKey();
318	        }
319	        return VisitStmt(op->body);
320	      }
321	
322	      if (op->attr_key == tl::attr::kCodeBlockEntryName) {
323	        if (auto str = op->value.as<StringImmNode>()) {
324	          *code_block_entry_name_ = str->value;
325	        } else {
326	          LOG(FATAL) << "Expected `" << tl::attr::kCodeBlockEntryName
327	                     << "` AttrStmt to carry a StringImm value, but got "
328	                     << op->value->GetTypeKey();
329	        }
330	        return VisitStmt(op->body);
331	      }
332	
333	      return tirx::StmtMutator::VisitStmt_(op);
334	    }
335	
336	    Optional<String> *code_block_source_;
337	    Optional<String> *code_block_entry_name_;
338	  };
339	
340	  class BufferUseRemapper : public tirx::StmtExprMutator {
341	  public:
342	    explicit BufferUseRemapper(Map<tirx::Buffer, tirx::Buffer> buffer_remap)
343	        : explicit_buffer_remap_(std::move(buffer_remap)) {}
344	
345	  private:
346	    tirx::Buffer VisitBufferUse(const tirx::Buffer &buffer) final {
347	      if (auto it = explicit_buffer_remap_.find(buffer);
348	          it != explicit_buffer_remap_.end()) {
349	        return (*it).second;
350	      }
351	      return tirx::StmtExprMutator::VisitBufferUse(buffer);
352	    }
353	
354	    Map<tirx::Buffer, tirx::Buffer> explicit_buffer_remap_;
355	  };
356	
357	  // Wrap body with assumes, substituting variables in assumes with the
358	  // corresponding variables in the device body based on name_hint matching.
359	  // This substitution is necessary because host-side assume variables may be
360	  // different Var objects from device-side parameters, even if they have the
361	  // same name. We always perform substitution to ensure ConvertSSA sees
362	  // consistent variable references.
363	  Stmt wrapBodyWithHostSideAssumes(
364	      Stmt body,
365	      const std::unordered_map<std::string, tirx::Var> &name_to_var) {
366	    // Build substitution map: assume_var -> body_var
367	    // Always substitute if we find a matching name, regardless of whether
368	    // it's the same object. This ensures ConvertSSA treats them as the same
369	    // variable.
370	    auto substitute_func =
371	        [&name_to_var](const tirx::Var &var) -> Optional<PrimExpr> {
372	      auto it = name_to_var.find(var->name_hint);
373	      if (it != name_to_var.end()) {
374	        return it->second;
375	      }
376	      return Optional<PrimExpr>();
377	    };
378	
379	    for (auto it = host_assumes_.rbegin(); it != host_assumes_.rend(); ++it) {
380	      // Substitute variables in the assume condition
381	      PrimExpr original_node = Downcast<PrimExpr>((*it)->node);
382	      PrimExpr substituted_node =
383	          tirx::Substitute(original_node, substitute_func);
384	      body = AttrStmt(substituted_node, tirx::attr::tilelang_assume,
385	                      (*it)->value, body);
386	    }
387	    return body;
388	  }
389	
390	  static Stmt WrapBodyWithRuntimeChecks(
391	      Stmt body, const std::vector<RuntimeCheckInfo> &runtime_checks) {
392	    for (auto it = runtime_checks.rbegin(); it != runtime_checks.rend(); ++it) {
393	      body = AttrStmt(it->condition, tirx::attr::tilelang_assume, it->message,
394	                      std::move(body), it->span);
395	      body = AttrStmt(it->condition, tl::attr::kAssumeRequiresRuntimeCheck,
396	                      it->message, std::move(body), it->span);
397	    }
398	    return body;
399	  }
400	
401	  tirx::Stmt SplitDeviceFunc(tirx::Stmt body, tvm::Target device_target) {
402	    code_block_source_ = std::nullopt;
403	    code_block_entry_name_ = std::nullopt;
404	    body = SourceKernelAttrExtractor::Extract(
405	        std::move(body), &code_block_source_, &code_block_entry_name_);
406	
407	    // Normal kernels infer device parameters from use-def of the device body.
408	    // Source kernels have no meaningful DSL body, so their device signature
409	    // must be reconstructed explicitly from the host PrimFunc signature and
410	    // buffer metadata.
411	    auto [old_params, buffers_to_declare] =
412	        [&]() -> std::tuple<Array<tirx::Var>, Array<tirx::Buffer>> {
413	      if (code_block_source_) {
414	        return CollectSourceKernelSignature();
415	      }
416	
417	      tirx::VarUseDefAnalyzer use_def(/*defined_vars=*/{},
418	                                      /*visit_thread_extent=*/true);
419	      use_def(body);
420	
421	      std::vector<tirx::Var> params{use_def.undefined_.begin(),
422	                                    use_def.undefined_.end()};
423	      SortDeviceParams(&params);
424	      return {Array<tirx::Var>(params.begin(), params.end()),
425	              use_def.undefined_buffers_};
426	    }();
427	
428	    // Runtime-check markers written inside a device region are otherwise
429	    // removed from the host function when the region is replaced by a kernel
430	    // launch. Preserve checks that the host can evaluate from scalar kernel
431	    // parameters so MakePackedAPI can turn them into runtime assertions.
432	    // Checks involving thread/block variables, local bindings, buffer loads,
433	    // calls, or conditional scopes remain device-only optimizer assumptions.
434	    std::vector<RuntimeCheckInfo> host_runtime_checks =
435	        DeviceRuntimeCheckCollector::Collect(body, old_params);
436	
437	    // Runtime checks execute in the host launcher. Their paired tl.assume
438	    // attributes remain in the device body as optimizer facts.
439	    body = RuntimeCheckMarkerRemover::Remove(std::move(body));
440	
441	    // Create new parameter variables for the device function to avoid sharing
442	    // Var objects with the host function. This prevents ConvertSSA from
443	    // incorrectly renaming variables when it processes multiple functions.
444	    Array<tirx::Var> params;
445	    Map<tirx::Var, PrimExpr> var_remap;
446	    std::unordered_map<std::string, tirx::Var> name_to_var;
447	    for (const auto &old_var : old_params) {
448	      tirx::Var new_var(old_var->name_hint, old_var->type_annotation);
449	      params.push_back(new_var);
450	      var_remap.Set(old_var, new_var);
451	      name_to_var[old_var->name_hint] = new_var;
452	    }
453	
454	    // Substitute old variables with new ones in the body
455	    body = tirx::Substitute(body, var_remap);
456	
457	    // Also remap buffers to use new variables
458	    Array<tirx::Buffer> new_buffers_to_declare;
459	    Map<tirx::Buffer, tirx::Buffer> buffer_remap;
460	    for (const auto &buf : buffers_to_declare) {
461	      auto new_shape = buf->shape.Map(
462	          [&](const PrimExpr &e) { return tirx::Substitute(e, var_remap); });
463	      auto new_strides = buf->strides.Map(
464	          [&](const PrimExpr &e) { return tirx::Substitute(e, var_remap); });
465	      auto new_elem_offset = tirx::Substitute(buf->elem_offset, var_remap);
466	      auto new_data = var_remap.count(buf->data)
467	                          ? Downcast<tirx::Var>(var_remap[buf->data])
468	                          : buf->data;
469	      tirx::Buffer new_buf(new_data, buf->dtype, new_shape, new_strides,
470	                           new_elem_offset, buf->name, buf->data_alignment,
471	                           buf->offset_factor, buf->buffer_type,
472	                           buf->axis_separators, buf->span);
473	      buffer_remap.Set(buf, new_buf);
474	      new_buffers_to_declare.push_back(new_buf);
475	    }
476	    body = BufferUseRemapper(buffer_remap)(std::move(body));
477	    buffers_to_declare = new_buffers_to_declare;
478	
479	    // CodeGenCPU is used for some device-side targets, such as
480	    // "ext_dev", and expects to be able to return a int32_t status
481	    // code.
482	
483	    bool can_propagate_errors = [&]() {
484	      auto kind = device_target->GetTargetDeviceType();
485	      return kind == kDLCPU || kind == kDLExtDev || kind == kDLHexagon;
486	    }();
487	    IntImm success(DataType::Int(32), 0);
488	    Type kernel_ret_type;
489	    if (can_propagate_errors) {
490	      kernel_ret_type = PrimType(DataType::Int(32));
491	      body = tirx::SeqStmt::Flatten(body, tirx::Evaluate(ret(success)));
492	    } else {
493	      kernel_ret_type = VoidType();
494	    }
495	
496	    // Declare necessary buffers for the device side.
497	    for (tirx::Buffer buf : buffers_to_declare) {
498	      body = tirx::SeqStmt({tirx::DeclBuffer(buf), std::move(body)});
499	    }
500	
501	    // Copy assumes from host-side to device-side, with variable substitution.
502	    // This must be done after DeclBuffer so that assumes are at the outermost
503	    // level of the function body. This ensures ConvertSSA correctly identifies
504	    // that assume variables refer to function parameters.
505	    body = wrapBodyWithHostSideAssumes(body, name_to_var);
506	
507	    // Remap non_restrict_params to use new parameter variables
508	    Array<tirx::Var> remapped_non_restrict_params;
509	    for (const auto &old_var : non_restrict_params_) {
510	      if (var_remap.count(old_var)) {
511	        remapped_non_restrict_params.push_back(
512	            Downcast<tirx::Var>(var_remap[old_var]));
513	      } else {
514	        remapped_non_restrict_params.push_back(old_var);
515	      }
516	    }
517	
518	    tirx::PrimFunc device_func(params, body, kernel_ret_type);
519	    Map<String, Any> device_attrs = {
520	        {tvm::attr::kTarget, device_target},
521	        {tirx::attr::kNoAlias, true},
522	        {tirx::attr::kIsGlobalFunc, true},
523	        {tl::attr::kNonRestrictParams, remapped_non_restrict_params}};
524	    if (cluster_dims_.defined()) {
525	      device_attrs.Set("cluster_dims", cluster_dims_.value());
526	    }
527	    if (!smem_alignment_map_.empty()) {
528	      device_attrs.Set(tl::kSmemAlignmentMap, smem_alignment_map_);
529	    }
530	    if (code_block_source_) {
531	      device_attrs.Set(tl::attr::kCodeBlockSource, code_block_source_.value());
532	    }
533	    device_func = WithAttrs(std::move(device_func), device_attrs);
534	
535	    GlobalVar kernel_symbol_global = var_supply_();
536	    if (code_block_entry_name_) {
537	      kernel_symbol_global = GlobalVar(code_block_entry_name_.value());
538	    }
539	
540	    (*device_mod_)->Add(kernel_symbol_global, device_func);
541	    // Use old_params as call arguments (host-side variables)
542	    Array<PrimExpr> args =
543	        old_params.Map([](const tirx::Var &var) -> PrimExpr { return var; });
544	
545	    Stmt host_call;
546	    if (can_propagate_errors) {
547	      tirx::Var kernel_error_code("kernel_error_code", success->dtype);
548	      tirx::Call kernel_call(success->dtype, kernel_symbol_global, args);
549	      tirx::Stmt assert_success = tirx::AssertStmt(
550	          kernel_error_code == success, tirx::StringImm("RuntimeError"),
551	          Array<tirx::StringImm>(
552	              {tirx::StringImm("Error executing compute kernel")}));
553	      host_call = tirx::SeqStmt(
554	          {tirx::Bind(kernel_error_code, kernel_call), assert_success});
555	    } else {
556	      host_call = tirx::Evaluate(
557	          tirx::Call(DataType::Void(), kernel_symbol_global, args));
558	    }
559	    return WrapBodyWithRuntimeChecks(std::move(host_call), host_runtime_checks);
560	  }
561	
562	  // target ir module
563	  IRModule *device_mod_;
564	  // Generate new GlobalVar for the kernel
565	  std::function<GlobalVar()> var_supply_;
566	  // Collect assumes in host side
567	  Array<tirx::AttrStmt> host_assumes_;
568	};
569	
570	tirx::PrimFunc SplitHostDevice(tirx::PrimFunc func, IRModule *device_mod,
571	                               std::function<GlobalVar()> var_supply) {
572	  HostDeviceSplitter splitter(device_mod, std::move(var_supply));
573	  splitter.SetHostFuncSignature(func);
574	  // Propagate non-restrict parameter list from host func to device kernels
575	  if (auto opt =
576	          func->GetAttr<Array<tirx::Var>>(tl::attr::kNonRestrictParams)) {
577	    splitter.SetNonRestrictParams(opt.value());
578	    // Remove the attribute from host-side PrimFunc; it only matters for device
579	    // codegen.
580	    func = tvm::WithoutAttr(std::move(func), tl::attr::kNonRestrictParams);
581	  }
582	  // Propagate cluster_dims from host func to device kernel.
583	  // LowerOpaqueBlock sets this attr on the pre-split kernel; after splitting
584	  // it must live on the device side so the codegen can emit a cluster launch.
585	  if (auto opt = func->GetAttr<Array<Integer>>("cluster_dims")) {
586	    splitter.SetClusterDims(opt.value());
587	    func = tvm::WithoutAttr(std::move(func), "cluster_dims");
588	  }
589	  // Propagate per-buffer shared-memory alignment requirements collected by
590	  // LowerTileOp onto the device kernel, where MergeSharedMemoryAllocations
591	  // consumes them.
592	  if (auto opt = func->GetAttr<Map<String, IntImm>>(tl::kSmemAlignmentMap)) {
593	    splitter.SetSmemAlignmentMap(opt.value());
594	    func = tvm::WithoutAttr(std::move(func), tl::kSmemAlignmentMap);
595	  }
596	
597	  if (auto body = splitter(func->body); !body.same_as(func->body)) {
598	    func.CopyOnWrite()->body = body;
599	  } else if (!splitter.found_device_region()) {
600	    if (auto target = func->GetAttr<Target>(tvm::attr::kTarget)) {
601	      auto device_target = target.value().WithoutHost();
602	      if (device_target.defined() &&
603	          func->HasNonzeroAttr(tirx::attr::kIsEntryFunc) &&
604	          tirx::is_no_op(func->body)) {
605	        if (auto forced = splitter.ForceSplit(func->body, device_target);
606	            !forced.same_as(func->body)) {
607	          func.CopyOnWrite()->body = forced;
608	        }
609	      }
610	    }
611	  }
612	  return func;
613	}
614	
615	namespace transform {
616	
617	tvm::transform::Pass SplitHostDevice() {
618	  auto pass_func = [](IRModule mod, tvm::transform::PassContext ctx) {
619	    tvm::GlobalVarSupply global_var_supply(mod);
620	
621	    IRModule device_mod = IRModule(Map<GlobalVar, BaseFunc>({}));
622	    IRModule updates = IRModule(Map<GlobalVar, BaseFunc>({}));
623	
624	    for (const auto &[gvar, base_func] : mod->functions) {
625	      if (auto opt = base_func.as<tirx::PrimFunc>()) {
626	        tirx::PrimFunc func = opt.value();
627	
628	        auto global_symbol = func->GetAttr<String>(tvm::attr::kGlobalSymbol);
629	        auto name_prefix = global_symbol.value_or(gvar->name_hint);
630	        auto kernel_name = name_prefix + "_kernel";
631	        auto var_supply = [&global_var_supply, &kernel_name]() -> GlobalVar {
632	          return global_var_supply->FreshGlobal(kernel_name, false);
633	        };
634	
635	        func = ::tvm::tl::SplitHostDevice(std::move(func), &device_mod,
636	                                          var_supply);
637	        if (!func.same_as(base_func)) {
638	          updates->Add(gvar, func);
639	        }
640	      }
641	    }
642	    mod->Update(updates);
643	    mod->Update(device_mod);
644	    return tirx::transform::ConvertSSA()(mod);
645	  };
646	
647	  return tvm::transform::CreateModulePass(pass_func, 0, "tl.SplitHostDevice",
648	                                          {});
649	}
650	
651	TVM_FFI_STATIC_INIT_BLOCK() {
652	  namespace refl = reflection;
653	  refl::GlobalDef().def("tl.transform.SplitHostDevice", SplitHostDevice);
654	}
655	
656	} // namespace transform
657	} // namespace tl
658	} // namespace tvm
