54	class ReturnRewriter : public StmtMutator {
55	public:
56	  explicit ReturnRewriter(Var ret_var) : ret_var_(ret_var) {}
57	
58	  Stmt VisitStmt_(const ForNode *node) override {
59	    if (node->kind == ForKind::kParallel)
60	      in_parallel_ += 1;
61	    Stmt ret = StmtMutator::VisitStmt_(node);
62	    if (node->kind == ForKind::kParallel)
63	      in_parallel_ -= 1;
64	    return ret;
65	  }
66	
67	  Stmt VisitStmt_(const EvaluateNode *node) override {
68	    Stmt ret = StmtMutator::VisitStmt_(node);
69	    const EvaluateNode *eval = ret.as<EvaluateNode>();
70	    ICHECK(eval);
71	    if (const CallNode *call = eval->value.as<CallNode>()) {
72	      if (call->op.same_as(builtin::ret())) {
73	        ICHECK_EQ(in_parallel_, 0)
74	            << "tir.ret cannot be used in parallel scope.";
75	        ICHECK_EQ(call->args.size(), 1) << "tir.ret expect a single argument.";
76	        ret = WriteToOut(call->args[0]);
77	      }
78	    }
79	    return ret;
80	  }
