82	private:
83	  struct ConvertedInfo {
84	    int type_index{-1};
85	    PrimExpr expr;
86	  };
87	
88	  ConvertedInfo ConvertForFFI(const PrimExpr &val) {
89	    ConvertedInfo info;
90	
91	    // convert val's data type to FFI data type, return type code
92	    DataType dtype = val.dtype();
93	    if (dtype.is_bool()) {
94	      info.type_index = TypeIndex::kTVMFFIBool;
95	      info.expr = Cast(DataType::Int(64), val);
96	
97	    } else if (dtype.is_int() || dtype.is_uint()) {
98	      info.type_index = TypeIndex::kTVMFFIInt;
99	      info.expr = Cast(DataType::Int(64), val);
100	    } else if (dtype.is_float()) {
101	      info.type_index = TypeIndex::kTVMFFIFloat;
102	      info.expr = Cast(DataType::Float(64), val);
103	    } else if (dtype.is_void()) {
104	      info.type_index = TypeIndex::kTVMFFINone;
105	      info.expr = val;
106	    } else {
107	      LOG(FATAL) << "data type " << dtype << " not supported yet";
108	    }
109	
110	    return info;
111	  }
112	
113	  Stmt WriteToOut(PrimExpr val) {
114	    auto info = ConvertForFFI(val);
115	    Stmt store_tindex = tirx::Evaluate(tirx::Call(
116	        DataType::Int(32), tirx::builtin::tvm_struct_set(),
117	        {ret_var_, IntImm(DataType::Int(32), 0),
118	         IntImm(DataType::Int(32), tirx::builtin::kTVMFFIAnyTypeIndex),
119	         IntImm(DataType::Int(32), info.type_index)}));
120	    Stmt store_zero_padding = tirx::Evaluate(tirx::Call(
121	        DataType::Int(32), tirx::builtin::tvm_struct_set(),
122	        {ret_var_, IntImm(DataType::Int(32), 0),
123	         IntImm(DataType::Int(32), tirx::builtin::kTVMFFIAnyZeroPadding),
124	         IntImm(DataType::Int(32), 0)}));
125	    Stmt store_val = tirx::Evaluate(tirx::Call(
126	        DataType::Int(32), tirx::builtin::tvm_struct_set(),
127	        {ret_var_, IntImm(DataType::Int(32), 0),
128	         IntImm(DataType::Int(32), tirx::builtin::kTVMFFIAnyUnionValue),
129	         info.expr}));
130	    Stmt ret_zero = Evaluate(tvm::ret(0));
131	    return SeqStmt({store_tindex, store_zero_padding, store_val, ret_zero});
132	  }
133	
134	  Var ret_var_;
135	  int in_parallel_{0};
136	};
