139	public:
140	  static Optional<Stmt> Apply(const Map<GlobalVar, String> &packed_func_methods,
141	                              Stmt stmt) {
142	    SubroutineCallRewriter rewriter(packed_func_methods);
143	    stmt = rewriter.VisitStmt(stmt);
144	    if (rewriter.made_change_) {
145	      return stmt;
146	    } else {
147	      return std::nullopt;
148	    }
149	  }
