151	private:
152	  explicit SubroutineCallRewriter(
153	      const Map<GlobalVar, String> &packed_func_methods)
154	      : packed_func_methods(packed_func_methods) {}
155	
156	  PrimExpr VisitExpr_(const CallNode *op) override {
157	    auto node = Downcast<Call>(StmtExprMutator::VisitExpr_(op));
158	
159	    if (auto *gvar_ptr = node->op.as<GlobalVarNode>()) {
160	      auto gvar = GetRef<GlobalVar>(gvar_ptr);
161	      if (auto symbol = packed_func_methods.Get(gvar)) {
162	        Array<PrimExpr> cpacked_args;
163	        cpacked_args.push_back(tirx::StringImm(symbol.value()));
164	        for (auto arg : node->args) {
165	          cpacked_args.push_back(arg);
166	        }
167	
168	        // push an empty handle to be compatible with current cpacked convention
169	        cpacked_args.push_back(tirx::make_zero(DataType::Handle()));
170	        made_change_ = true;
171	        return tirx::Call(node->dtype, tirx::builtin::tvm_call_cpacked(),
172	                          cpacked_args);
173	      }
174	    }
175	
176	    return node;
177	  }
178	  const Map<GlobalVar, String> &packed_func_methods;
179	  bool made_change_{false};
