188	class AssumeRuntimeCheckExtractor : public StmtMutator {
189	public:
190	  static Stmt Extract(Stmt body,
191	                      std::vector<AssumeRuntimeCheck> *runtime_checks) {
192	    AssumeRuntimeCheckExtractor extractor(runtime_checks);
193	    return extractor(std::move(body));
