196	private:
197	  explicit AssumeRuntimeCheckExtractor(
198	      std::vector<AssumeRuntimeCheck> *runtime_checks)
199	      : runtime_checks_(runtime_checks) {}
200	
201	  Stmt VisitStmt_(const AttrStmtNode *op) final {
202	    if (op->attr_key != tl::attr::kAssumeRequiresRuntimeCheck) {
203	      return StmtMutator::VisitStmt_(op);
204	    }
205	
206	    PrimExpr condition = Downcast<PrimExpr>(op->node);
207	    Array<StringImm> message_parts;
208	    if (const auto *message = op->value.as<StringImmNode>()) {
209	      message_parts.push_back(GetRef<StringImm>(message));
210	    } else {
211	      std::ostringstream os;
212	      os << "Assume: " << condition;
213	      message_parts.push_back(StringImm(os.str()));
214	    }
215	
216	    if (conditional_scope_depth_ != 0) {
217	      // Conditional checks cannot be moved to the packed-function entry
218	      // without changing their execution semantics. Keep only the paired
219	      // tl.assume, matching SplitHostDevice's conservative lifting policy.
220	      return VisitStmt(op->body);
221	    }
222	    runtime_checks_->push_back({condition, std::move(message_parts), op->span});
223	    return VisitStmt(op->body);
224	  }
