264	/* \brief Return the global_symbol of the function, if it should be updated
265	 *
266	 * \param func The function to be inspected
267	 *
268	 * \returns The global_symbol to be used for the function at call
269	 * sites, or std::nullopt if the function is to remain unchanged.
270	 */
271	Optional<String> RequiresPackedAPI(const PrimFunc &func) {
272	  // A function with an explicit calling convention has already been
273	  // lowered, and should not be modified.
274	  if (auto opt = func->GetAttr<Integer>(tvm::attr::kCallingConv)) {
275	    if (CallingConv(opt.value()->value) != CallingConv::kDefault) {
276	      return std::nullopt;
277	    }
278	  }
279	
280	  // Source kernels must stay as direct GlobalVar calls until
281	  // LowerDeviceKernelLaunch can turn them into device launches using the
282	  // selected external CUDA entry symbol.
283	  if (func->GetAttr<String>(tl::attr::kCodeBlockSource)) {
284	    return std::nullopt;
285	  }
286	
287	  // Internal function calls do not need the PackedFunc API
288	  auto global_symbol = func->GetAttr<String>(tvm::attr::kGlobalSymbol);
289	  if (!global_symbol) {
290	    return std::nullopt;
291	  }
292	
293	  return global_symbol;
294	}
295	
296	PrimFunc MakePackedAPI(PrimFunc func) {
297	  auto global_symbol = RequiresPackedAPI(func);
298	  if (!global_symbol) {
299	    return func;
300	  }
301	  std::string name_hint = global_symbol.value();
302	
303	  Target target = [&]() {
304	    auto opt = func->GetAttr<Target>(tvm::attr::kTarget);
305	    ICHECK(opt) << "MakePackedAPI required the function to be annotated with "
306	                   "tvm::attr::kTarget ("
307	                << tvm::attr::kTarget
308	                << "), but the function only has attributes " << func->attrs;
309	    return opt.value();
310	  }();
311	  int target_device_type = target->GetTargetDeviceType();
312	
313	  // A function without a host target has already been lowered.
314	  Target target_host;
315	  if (auto opt = target->GetHost()) {
316	    target_host = opt.value();
317	  } else {
318	    return func;
319	  }
320	
321	  auto *func_ptr = func.CopyOnWrite();
322	  std::vector<AssumeRuntimeCheck> assume_runtime_checks;
323	  func_ptr->body = AssumeRuntimeCheckExtractor::Extract(func_ptr->body,
324	                                                        &assume_runtime_checks);
325	  // set the global symbol to the packed function name
326	  const Stmt nop = Evaluate(0);
327	  int num_args = static_cast<int>(func_ptr->params.size());
328	
329	  // Data field definitions
330	  // The packed fields
331	  Var v_self_handle("self_handle", DataType::Handle());
332	  Var v_packed_args("args", DataType::Handle());
333	  Var v_num_packed_args("num_args", DataType::Int(32));
334	  Var v_result("result", PointerType(PrimType(DataType::Void())));
335	
336	  // The device context
337	  Var device_id("dev_id");
338	  Integer device_type(target_device_type);
339	  // seq_init gives sequence of initialization
340	  // seq_check gives sequence of later checks after init
341	  std::vector<Stmt> seq_init, seq_check, arg_buffer_declarations;
342	  std::unordered_map<const VarNode *, PrimExpr> vmap;
343	  TVMFFIABIBuilder binder(&vmap);
344	
345	  // ---------------------------
346	  // local function definitions
347	  // load i-th argument as type t
348	  auto f_load_arg_value = [&](DataType arg_type, int i) {
349	    Array<PrimExpr> call_args{
350	        v_packed_args, IntImm(DataType::Int(32), i),
351	        IntImm(DataType::Int(32), builtin::kTVMFFIAnyUnionValue)};
352	    // load 64 bit version
353	    DataType api_type = APIType(arg_type);
354	    PrimExpr res = Call(api_type, builtin::tvm_struct_get(), call_args);
355	    // cast to the target version.
356	    if (api_type != arg_type) {
357	      res = Cast(arg_type, res);
358	    }
359	    return res;
360	  };
361	
362	  // Assert correct type codes for each argument.  This must be done
363	  // *before* any initialization steps produced by
364	  // `binder.BindDLTensor()`.  The validity of those initialization
365	  // steps depends on the correct types being present, and must not
366	  // occur before the type codes are actually checked.
367	  seq_init.push_back(
368	      MakeAssertEQ(v_num_packed_args, num_args, [&]() -> std::string {
369	        std::ostringstream error_message;
370	        error_message << name_hint << ": num_args should be " << num_args;
371	        return error_message.str();
372	      }()));
373	
374	  if (num_args > 0) {
375	    seq_init.push_back(
376	        MakeAssertNotNull(v_packed_args, name_hint + ": args pointer is NULL"));
377	  }
378	
379	  // Need to delay binding of the buffers, in case some arguments also
380	  // appear in the buffer.
381	  std::vector<std::pair<PrimExpr, Var>> var_def;
382	  std::vector<std::pair<Var, Buffer>> buffer_def;
383	
384	  // First, collect a reverse map from Buffer->data var to parameter var so we
385	  // can detect whether a buffer is actually used by the function body. In
386	  // addition, collect variables that appear in the buffer's shape/stride so we
387	  // can consider uses of those symbols as a use of the buffer itself.
388	  std::unordered_map<const VarNode *, const VarNode *> data_var2param;
389	  std::unordered_map<const VarNode *, std::vector<const VarNode *>>
390	      shape_var2params;
391	  for (const auto &kv : func_ptr->buffer_map) {
392	    const Var &param = kv.first;
393	    const Buffer &buf = kv.second;
394	    data_var2param[buf->data.get()] = param.get();
395	    auto record_shape_vars = [&](const PrimExpr &e) {
396	      PostOrderVisit(e, [&](const ObjectRef &n) {
397	        if (const auto *v = n.as<VarNode>()) {
398	          shape_var2params[v].push_back(param.get());
399	        }
400	      });
401	    };
402	    for (const PrimExpr &e : buf->shape)
403	      record_shape_vars(e);
404	    for (const PrimExpr &e : buf->strides)
405	      record_shape_vars(e);
406	    if (buf->elem_offset.defined())
407	      record_shape_vars(buf->elem_offset);
408	  }
409	
410	  // A visitor that records
411	  //  - which parameter buffers are used via their data var (load/store/direct),
412	  //  - which shape/stride/offset symbols are referenced in the body.
413	  // Shape symbols are not immediately attributed to all carrier buffers here;
414	  // a minimal carrier set is selected after visiting.
415	  struct UsedBufferDetector : public StmtExprVisitor {
416	    UsedBufferDetector(
417	        const std::unordered_map<const VarNode *, const VarNode *> &data2param,
418	        const std::unordered_map<const VarNode *, std::vector<const VarNode *>>
419	            &shape2params)
420	        : data2param(data2param), shape2params(shape2params) {}
421	    void VisitExpr_(const VarNode *op) override {
422	      auto it = data2param.find(op);
423	      if (it != data2param.end()) {
424	        used_params_by_data.insert(it->second);
425	      }
426	      auto it2 = shape2params.find(op);
427	      if (it2 != shape2params.end()) {
428	        used_shape_vars.insert(op);
429	      }
430	      StmtExprVisitor::VisitExpr_(op);
431	    }
432	    void VisitStmt_(const BufferStoreNode *op) override {
433	      auto it = data2param.find(op->buffer->data.get());
434	      if (it != data2param.end()) {
435	        used_params_by_data.insert(it->second);
436	      }
437	      StmtExprVisitor::VisitStmt_(op);
438	    }
439	    void VisitExpr_(const BufferLoadNode *op) override {
440	      auto it = data2param.find(op->buffer->data.get());
441	      if (it != data2param.end()) {
442	        used_params_by_data.insert(it->second);
443	      }
444	      StmtExprVisitor::VisitExpr_(op);
445	    }
446	
447	    const std::unordered_map<const VarNode *, const VarNode *> &data2param;
448	    const std::unordered_map<const VarNode *, std::vector<const VarNode *>>
449	        &shape2params;
450	    std::unordered_set<const VarNode *> used_params_by_data;
451	    std::unordered_set<const VarNode *> used_shape_vars;
452	  };
453	
454	  UsedBufferDetector detector(data_var2param, shape_var2params);
455	  detector(func_ptr->body);
456	
457	  // Build the packed argument handling. While doing so, keep track of whether
458	  // each parameter buffer is actually used. Unused input buffers can be
459	  // nullable and do not require DLTensor field dereferences.
460	  //
461	  // Start from buffers used via data-var (definitely non-NULL), then for each
462	  // referenced shape symbol pick a minimal "carrier" buffer that provides the
463	  // symbol. Prefer carriers that are already used-by-data; otherwise pick one
464	  // arbitrary carrier to ensure the symbol is bound.
465	  std::unordered_set<const VarNode *> used_param_buffers =
466	      detector.used_params_by_data;
467	  for (const VarNode *sym : detector.used_shape_vars) {
468	    auto it = shape_var2params.find(sym);
469	    if (it == shape_var2params.end())
470	      continue;
471	    const auto &carriers = it->second;
472	    bool has_used_carrier = false;
473	    for (const VarNode *p : carriers) {
474	      if (used_param_buffers.count(p)) {
475	        has_used_carrier = true;
476	        break;
477	      }
478	    }
479	    // NOTE: With the new nullable shape binding logic in
480	    // TVMFFIABIBuilder::BindDLTensors, we no longer need to force one carrier
481	    // to be non-NULL. The binder will:
482	    // 1. Assert that at least one carrier is non-NULL at runtime
483	    // 2. Use cascaded if_then_else to read from the first non-NULL carrier
484	    // So we can allow all carriers to be nullable.
485	    // if (!has_used_carrier && !carriers.empty()) {
486	    //   used_param_buffers.insert(carriers.front());
487	    // }
488	  }
489	
490	  for (int i = 0; i < static_cast<int>(func_ptr->params.size()); ++i) {
491	    Var param = func_ptr->params[i];
492	    PrimExpr arg_value;
493	    // type index checks
494	    Var type_index(param->name_hint + ".type_index", DataType::Int(32));
495	    seq_init.push_back(SeqStmt(
496	        {tirx::Bind(type_index,
497	                    tirx::Call(DataType::Int(32), builtin::tvm_struct_get(),
498	                               {v_packed_args, IntImm(DataType::Int(32), i),
499	                                IntImm(DataType::Int(32),
500	                                       builtin::kTVMFFIAnyTypeIndex)})),
501	         nop}));
502	    DataType dtype = param.dtype();
503	    if (dtype.is_handle()) {
504	      std::ostringstream msg;
505	      // Prefer the Buffer name if available; otherwise, fall back to param name
506	      // (trim _handle).
507	      std::string display_name;
508	      auto it_buf = func_ptr->buffer_map.find(param);
509	      if (it_buf != func_ptr->buffer_map.end()) {
510	        const auto &kv = *it_buf;
511	        display_name = kv.second->data->name_hint;
512	      } else {
513	        display_name = param->name_hint;
514	        const char *suffix = "_handle";
515	        if (display_name.size() >= 7 &&
516	            display_name.compare(display_name.size() - 7, 7, suffix) == 0) {
517	          display_name.erase(display_name.size() - 7);
518	        }
519	      }
520	      msg << "kernel " << name_hint << " input " << display_name
521	          << " expected pointer or tensor handle";
522	      seq_init.emplace_back(AssertStmt(
523	          type_index == TypeIndex::kTVMFFINone ||
524	              type_index == TypeIndex::kTVMFFIOpaquePtr ||
525	              type_index == TypeIndex::kTVMFFIDLTensorPtr ||
526	              type_index >= TypeIndex::kTVMFFIStaticObjectBegin,
527	          tvm::tirx::StringImm("RuntimeError"),
528	          Array<tvm::tirx::StringImm>({tvm::tirx::StringImm(msg.str())})));
529	      // if type_index is Tensor, we need to add the offset of the DLTensor
530	      // header which always equals 16 bytes, this ensures that T.handle always
531	      // shows up as a DLTensor*
532	      const int64_t object_cell_offset = sizeof(TVMFFIObject);
533	      static_assert(object_cell_offset == 24);
534	      arg_value = f_load_arg_value(param.dtype(), i);
535	      PrimExpr handle_from_tensor =
536	          Call(DataType::Handle(), tirx::builtin::handle_add_byte_offset(),
537	               {arg_value, IntImm(DataType::Int(32), object_cell_offset)});
538	      arg_value = Select(type_index == TypeIndex::kTVMFFITensor,
539	                         handle_from_tensor, arg_value);
540	    } else if (dtype.is_bool()) {
541	      std::ostringstream msg;
542	      msg << "kernel " << name_hint << " scalar " << param->name_hint
543	          << " expected boolean";
544	      seq_init.emplace_back(AssertStmt(
545	          type_index == TypeIndex::kTVMFFIBool ||
546	              type_index == TypeIndex::kTVMFFIInt,
547	          tvm::tirx::StringImm("RuntimeError"),
548	          Array<tvm::tirx::StringImm>({tvm::tirx::StringImm(msg.str())})));
549	      arg_value =
550	          Cast(DataType::Bool(), f_load_arg_value(DataType::Int(64), i));
551	
552	    } else if (dtype.is_int() || dtype.is_uint()) {
553	      std::ostringstream msg;
554	      msg << "kernel " << name_hint << " scalar " << param->name_hint
555	          << " expected integer";
556	      seq_init.emplace_back(AssertStmt(
557	          type_index == TypeIndex::kTVMFFIInt ||
558	              type_index == TypeIndex::kTVMFFIBool,
559	          tvm::tirx::StringImm("RuntimeError"),
560	          Array<tvm::tirx::StringImm>({tvm::tirx::StringImm(msg.str())})));
561	      arg_value = f_load_arg_value(param.dtype(), i);
562	    } else {
563	      ICHECK(dtype.is_float());
564	      std::ostringstream msg;
565	      msg << "kernel " << name_hint << " scalar " << param->name_hint
566	          << " expected float";
567	      seq_init.emplace_back(AssertStmt(
568	          type_index == TypeIndex::kTVMFFIFloat ||
569	              type_index == TypeIndex::kTVMFFIInt ||
570	              type_index == TypeIndex::kTVMFFIBool,
571	          tvm::tirx::StringImm("RuntimeError"),
572	          Array<tvm::tirx::StringImm>({tvm::tirx::StringImm(msg.str())})));
573	      // use select so we can also handle int conversion to bool
574	      arg_value = tirx::Select(
575	          type_index == TypeIndex::kTVMFFIFloat,
576	          /* true_value = */ f_load_arg_value(param.dtype(), i),
577	          /* false_value = */
578	          Cast(param.dtype(), f_load_arg_value(DataType::Int(64), i)));
579	    }
580	    var_def.emplace_back(arg_value, param);
581	    if (func_ptr->buffer_map.count(param)) {
582	      // buffer binding now depends on type index
583	      // if the index is Tensor handle, we need to offset to get the DLTensor*
584	      buffer_def.emplace_back(param, func_ptr->buffer_map[param]);
585	    }
586	  }
587	
588	  // signature: (void* handle, TVMFFIAny* packed_args, int num_args, TVMFFIAny*
589	  // v_result)
590	  Array<Var> args{v_self_handle, v_packed_args, v_num_packed_args, v_result};
591	
592	  // Arg definitions are defined before buffer binding to avoid the use before
593	  // def errors.
594	  //
595	  // For example, for auto broadcasting, checks are required to guarantee that
596	  // either 0 or the original stride will be correctly used. Checks here have
597	  // to use the args that may have no let binding yet. Therefore, hoisting let
598	  // binding for args before buffer declaration is needed.
599	  for (const auto &[expr, param] : var_def) {
600	    binder.Bind(param, expr, name_hint + "." + param->name_hint, true);
601	  }
602	
603	  binder.BindDLTensors(buffer_def, device_type, device_id, name_hint,
604	                       used_param_buffers, detector.used_shape_vars);
605	  for (const auto &[var, buffer] : buffer_def) {
606	    // Prefer buffer data var name in diagnostics to avoid exposing low-level
607	    // handle vars
608	    arg_buffer_declarations.push_back(DeclBuffer(buffer));
609	  }
610	
611	  // reset global symbol to attach prefix
612	  func = WithAttrs(
613	      std::move(func),
614	      {{tvm::attr::kCallingConv, static_cast<int>(CallingConv::kCPackedFunc)},
615	       {tvm::attr::kTarget, target_host},
616	       {tvm::attr::kGlobalSymbol,
617	        symbol::tvm_ffi_symbol_prefix + global_symbol.value()}});
618	
619	  Stmt body = ReturnRewriter(v_result)(func_ptr->body);
620	  for (auto it = assume_runtime_checks.rbegin();
621	       it != assume_runtime_checks.rend(); ++it) {
622	    Stmt assertion = AssertStmt(it->condition, StringImm("RuntimeError"),
623	                                it->message_parts, it->span);
624	    body = SeqStmt::Flatten(std::move(assertion), std::move(body));
625	  }
626	  body = AttrStmt(make_zero(DataType::Int(32)), tirx::attr::compute_scope,
627	                  StringImm(name_hint + "_compute_"), body);
628	  // Set device context
629	  if (vmap.count(device_id.get())) {
630	    Any node = String("default");
631	    seq_check.push_back(AttrStmt(node, tirx::attr::device_id, device_id, nop));
632	    seq_check.push_back(
633	        AttrStmt(node, tirx::attr::device_type, device_type, nop));
634	
635	    if (runtime::DeviceAPI::NeedSetDevice(target_device_type)) {
636	      Stmt set_device =
637	          Evaluate(Call(DataType::Int(32), tirx::builtin::tvm_call_packed(),
638	                        {StringImm(runtime::symbol::tvm_set_device),
639	                         device_type, device_id}));
640	      body = SeqStmt({set_device, body});
641	    }
642	  }
643	
644	  // Return error code of zero on success
645	  body = SeqStmt({body, Evaluate(ret(Integer(0)))});
646	
647	  body = MergeNest({seq_init, binder.InitNest(), seq_check, binder.Asserts(),
648	                    arg_buffer_declarations},
649	                   body);
650	  func_ptr->body = body;
651	  func_ptr->params = args;
652	
653	  Array<Var> undefined = UndefinedVars(body, func_ptr->params);
654	
655	  ICHECK_EQ(undefined.size(), 0)
656	      << "In PrimFunc " << name_hint << " variables " << undefined
657	      << " are used, but are not passed in as API arguments";
658	
659	  func_ptr->buffer_map = Map<Var, Buffer>();
660	  func_ptr->ret_type = PrimType(DataType::Int(32));
661	  // return the function.
662	  return func;
663	}
664	
665	tvm::transform::Pass MakePackedAPI() {
666	  using tvm::transform::Pass;
667	  auto pass_func = [](IRModule mod, const tvm::transform::PassContext &ctx) {
668	    Map<GlobalVar, String> packed_func_methods;
669	    for (const auto &[gvar, base_func] : mod->functions) {
670	      if (auto opt = base_func.as<PrimFunc>()) {
671	        const auto &prim_func = opt.value();
672	        if (auto global_symbol = RequiresPackedAPI(prim_func)) {
673	          packed_func_methods.Set(gvar, global_symbol.value());
674	        }
675	      }
676	    }
677	
678	    IRModuleNode *mptr = mod.CopyOnWrite();
679	    IRModule updates;
680	
681	    for (const auto &[gvar, base_func] : mptr->functions) {
682	      if (auto opt = base_func.as<PrimFunc>()) {
683	        auto func = opt.value();
684	        auto orig_func = func;
685	
686	        if (auto body = SubroutineCallRewriter::Apply(packed_func_methods,
687	                                                      func->body)) {
688	          func.CopyOnWrite()->body = body.value();
689	        }
690	        func = MakePackedAPI(std::move(func));
691	        func = MergeIfStmtSubstitute(func);
692	
693	        if (!func.same_as(orig_func)) {
694	          updates->Add(gvar, func);
695	        }
696	      }
697	    }
698	
699	    if (!updates->functions.empty()) {
700	      mod.CopyOnWrite()->Update(updates);
701	    }
702	    return mod;
703	  };
704	
705	  return tvm::transform::CreateModulePass(pass_func, 0, "tl.MakePackedAPI", {});
706	}
707	
708	TVM_FFI_STATIC_INIT_BLOCK() {
709	  namespace refl = reflection;
710	  refl::GlobalDef().def("tl.transform.MakePackedAPI",
711	                        []() { return MakePackedAPI(); });
712	}
713	
714	} // namespace tl
715	} // namespace tvm
