#include "codegen_cuda.h"
#include "runtime/pack_args.h"
#include "runtime/thread_storage_scope.h"
#include "support/check.h"
#include "target/cuda/cuda_fallback_module.h"
#include "transform/common/attr.h"
#include <tvm/ir/cast.h>
#include <tvm/ir/transform.h>

namespace tvm {
namespace codegen {

using namespace ffi;

static std::string GetDeviceGlobalSymbol(const GlobalVar &gvar,
                                         const tirx::PrimFunc &f) {
  if (auto global_symbol = f->GetAttr<String>(tvm::attr::kGlobalSymbol)) {
    return static_cast<std::string>(global_symbol.value());
  }
  return gvar->name_hint;
}

static void ValidateUniqueDeviceGlobalSymbols(const IRModule &mod) {
  std::unordered_map<std::string, std::string> symbol_to_gvar;

  for (auto kv : mod->functions) {
    ICHECK(kv.second->IsInstance<tirx::PrimFuncNode>())
        << "Can only lower IR Module with PrimFuncs";
    auto gvar = Downcast<GlobalVar>(kv.first);
    auto f = Downcast<tirx::PrimFunc>(kv.second);
    std::string global_symbol = GetDeviceGlobalSymbol(gvar, f);

    auto [it, inserted] =
        symbol_to_gvar.emplace(global_symbol, gvar->name_hint);
    ICHECK(inserted)
        << "Duplicate CUDA kernel global_symbol `" << global_symbol
        << "` found on PrimFuncs `" << it->second << "` and `"
        << gvar->name_hint
        << "`. T.CUDASourceCodeKernel emits raw CUDA source without "
           "renaming, so CUDA entry names must be unique within the compiled "
           "module.";
  }
}

static Map<String, runtime::FunctionInfo> ExtractFuncInfo(const IRModule &mod) {
  Map<String, runtime::FunctionInfo> fmap;

  for (auto kv : mod->functions) {
    ICHECK(kv.second->IsInstance<tirx::PrimFuncNode>())
        << "Can only lower IR Module with PrimFuncs";
    auto f = Downcast<tirx::PrimFunc>(kv.second);

    Array<DLDataType> arg_types;
    Array<String> launch_param_tags;

    for (size_t i = 0; i < f->params.size(); ++i) {
      if (f->params[i]->dtype.is_handle()) {
        auto ptr = f->params[i]->type_annotation.as<PointerTypeNode>();
        if (ptr && ptr->storage_scope == "grid_constant") {
          arg_types.push_back(DataType(runtime::kDLGridConstant, 64, 1));
          continue;
        }
      }
      DataType dtype = f->params[i].dtype();
      if (dtype.is_bool())
        dtype = DataType::Int(32);
      arg_types.push_back(dtype);
    }
    if (f->HasNonzeroAttr(tl::attr::kHasGridSync)) {
      launch_param_tags.push_back(
          runtime::launch_param::kUseProgramaticDependentLaunch);
    }
    if (f->HasNonzeroAttr("use_cooperative_groups")) {
      launch_param_tags.push_back(runtime::launch_param::kUseCooperativeLaunch);
    }
    if (f->GetAttr<Array<Integer>>("cluster_dims").defined()) {
      launch_param_tags.push_back(runtime::launch_param::kClusterDimX);
      launch_param_tags.push_back(runtime::launch_param::kClusterDimY);
      launch_param_tags.push_back(runtime::launch_param::kClusterDimZ);
    }
    if (auto opt = f->GetAttr<Array<String>>(tirx::attr::kKernelLaunchParams)) {
      for (const auto &tag : opt.value()) {
        if (tag != runtime::launch_param::kClusterDimX &&
            tag != runtime::launch_param::kClusterDimY &&
            tag != runtime::launch_param::kClusterDimZ) {
          launch_param_tags.push_back(tag);
        }
      }
    }
    std::string sym = GetDeviceGlobalSymbol(Downcast<GlobalVar>(kv.first), f);
    fmap.Set(String(sym), runtime::FunctionInfo(String(sym), arg_types,
                                                launch_param_tags, {}));
  }
  return fmap;
}

Module BuildTileLangCUDA(IRModule mod, Target target) {
  bool output_ssa = false;
  CodeGenTileLangCUDA cg;
  cg.Init(output_ssa);

  ValidateUniqueDeviceGlobalSymbols(mod);
  if (const auto f = Function::GetGlobal("tilelang_callback_cuda_validate")) {
    (*f)(mod);
  }

  for (auto kv : mod->functions) {
    ICHECK(kv.second->IsInstance<PrimFuncNode>())
        << "CodeGenTileLangCUDA: Can only take PrimFunc";
    auto gvar = Downcast<GlobalVar>(kv.first);
    auto f = Downcast<PrimFunc>(kv.second);
    auto calling_conv = f->GetAttr<Integer>(tvm::attr::kCallingConv);
    ICHECK(calling_conv == CallingConv::kDeviceKernelLaunch);
    cg.AddFunction(gvar, f);
  }

  std::string code = cg.Finish();
  if (const auto f = Function::GetGlobal("tilelang_callback_cuda_postproc")) {
    code = (*f)(code, target).cast<std::string>();
  }
  std::string fmt = "ptx";
  std::string ptx;
  if (const auto f = Function::GetGlobal("tilelang_callback_cuda_compile")) {
    // Fetch current pass context config and pass into the compile callback
    tvm::transform::PassContext pass_ctx =
        tvm::transform::PassContext::Current();
    ptx = (*f)(code, target, pass_ctx->config).cast<std::string>();
    if (ptx[0] != '/')
      fmt = "cubin";
  } else {
    ICHECK(0);
  }
  Map<String, String> source_map;
  source_map.Set("cuda", code);
  return target::CUDAModuleCreateWithFallback(Bytes(ptx.data(), ptx.size()),
                                              String(fmt), ExtractFuncInfo(mod),
                                              source_map);
}

Module BuildTileLangCUDAWithoutCompile(IRModule mod, Target target) {
  bool output_ssa = false;
  CodeGenTileLangCUDA cg;
  cg.Init(output_ssa);

  ValidateUniqueDeviceGlobalSymbols(mod);
  if (const auto f = Function::GetGlobal("tilelang_callback_cuda_validate")) {
    (*f)(mod);
  }

  for (auto kv : mod->functions) {
    ICHECK(kv.second->IsInstance<PrimFuncNode>())
        << "CodeGenTileLangCUDA: Can only take PrimFunc";
    auto gvar = Downcast<GlobalVar>(kv.first);
    auto f = Downcast<PrimFunc>(kv.second);
    auto calling_conv = f->GetAttr<Integer>(tvm::attr::kCallingConv);
    ICHECK(calling_conv == CallingConv::kDeviceKernelLaunch);
    cg.AddFunction(gvar, f);
  }

  std::string code = cg.Finish();
  if (const auto f = Function::GetGlobal("tilelang_callback_cuda_postproc")) {
    code = (*f)(code, target).cast<std::string>();
  }
  Map<String, String> source_map;
  source_map.Set("cuda", code);
  // The no-compile path still needs a code payload and format for the CUDA
  // module container.  Keep a tiny dummy PTX payload; the generated CUDA source
  // is preserved in source_map for InspectSource/get_source.
  static constexpr const char kDummyPtx[] = "ptx";
  return target::CUDAModuleCreateWithFallback(
      Bytes(kDummyPtx, sizeof(kDummyPtx) - 1), String("ptx"),
      ExtractFuncInfo(mod), source_map);
}

TVM_FFI_STATIC_INIT_BLOCK() {
  namespace refl = reflection;
  refl::GlobalDef()
      .def("target.build.tilelang_cuda", BuildTileLangCUDA)
      .def("target.build.tilelang_cuda_without_compile",
           BuildTileLangCUDAWithoutCompile);
}

} // namespace codegen
} // namespace tvm

"""The profiler and convert to torch utils"""

from __future__ import annotations

from abc import ABC, abstractmethod
from collections.abc import Callable
from dataclasses import dataclass
from typing import Any

import torch

from tilelang.engine.param import KernelParam


@dataclass(frozen=True)
class CachedTextSource:
    text: str | None = None
    path: str | None = None


CachedTextSourceLike = CachedTextSource | str | None


class BaseKernelAdapter(ABC):
    func: Callable | None = None

    def __init__(self, mod, params: list[KernelParam], result_idx: list[int]) -> None:
        self.mod = mod
        self.params = params
        self.result_idx = self._legalize_result_idx(result_idx)
        self._post_init()

    def _legalize_result_idx(self, result_idx: list[int] | None) -> list[int]:
        params = self.params
        # result_idx is a list of indices of the output tensors
        if result_idx is None:
            result_idx = []
        elif isinstance(result_idx, int):
            if result_idx > len(params) or result_idx < -len(params):
                raise ValueError(f"result_idx should be an integer between {-len(params) - 1} and {len(params) - 1}")
            if result_idx < 0:
                result_idx = len(params) + result_idx
            result_idx = [result_idx]
        elif isinstance(result_idx, list):
            for i, idx in enumerate(result_idx):
                if idx >= len(params) or idx < -len(params):
                    raise ValueError(f"result_idx should be an integer between {-len(params) - 1} and {len(params) - 1}")
                if idx < 0:
                    result_idx[i] = len(params) + idx
        else:
            raise ValueError("result_idx should be a list of integers")

        return result_idx

    @abstractmethod
    def _convert_torch_func(self) -> callable:
        pass

    # --- Common helpers to align with PyTorch stream/device semantics ---
    @staticmethod
    def get_current_stream_functor() -> Callable[[], int]:
        """Return a callable that reads Torch's current CUDA stream pointer.

        The returned lambda yields the raw CUDA stream handle of the current
        PyTorch stream on the active device. It's a thunk (evaluated at call
        time) so that any upstream stream guards are respected. If CUDA is
        unavailable, it returns a lambda that yields 0.
        """
        if torch.cuda.is_available():
            try:
                torch.cuda._lazy_init()
                current_device = torch._C._cuda_getDevice
                get_stream = torch._C._cuda_getCurrentRawStream
                return lambda: get_stream(current_device())
            except Exception:
                # Fallback to Python API if internal handles are unavailable
                return lambda: int(torch.cuda.current_stream().cuda_stream)
        # CPU or CUDA unavailable: no stream semantics
        return lambda: 0

    @staticmethod
    def get_current_device_functor() -> Callable[[], torch.device]:
        """Return a callable that yields Torch's current device.

        Similar to the stream functor, we capture a callable that, when called,
        fetches the current device according to PyTorch. On CPU or when CUDA is
        unavailable, returns ``torch.device('cpu')``.
        """
        if torch.cuda.is_available():
            try:
                torch.cuda._lazy_init()
                current_device = torch._C._cuda_getDevice
                return lambda: torch.device("cuda", current_device())
            except Exception:
                return lambda: torch.device("cuda", torch.cuda.current_device())
        # CPU fallback
        return lambda: torch.device("cpu")

    def __call__(self, *args: Any, **kwds: Any) -> Any:
        return self.func(*args, **kwds)

    def get_kernel_source(self, kernel_only: bool = True) -> str:
        if kernel_only:
            return self.mod.imports[0].inspect_source()
        else:
            return self.mod.inspect_source() + "\n\n" + self.mod.imports[0].inspect_source()

    def _post_init(self):
        self.func = self._convert_torch_func()

    @staticmethod
    def _normalize_cached_text_source(source: CachedTextSourceLike) -> CachedTextSource:
        if isinstance(source, CachedTextSource):
            return source
        if source is None:
            return CachedTextSource()
        return CachedTextSource(text=source)

    def _set_cached_text_source(self, source_attr: str, path_attr: str, source: CachedTextSourceLike) -> CachedTextSource:
        source = self._normalize_cached_text_source(source)
        setattr(self, source_attr, source.text)
        setattr(self, path_attr, source.path)
        return source

    def _load_cached_text_source(self, source_attr: str, path_attr: str) -> str | None:
        source = getattr(self, source_attr, None)
        if source is not None:
            return source

        path = getattr(self, path_attr, None)
        if path is None:
            return None

        try:
            with open(path, encoding="utf-8") as file:
                source = file.read()
        except OSError:
            return None
        setattr(self, source_attr, source)
        return source

